<script setup>
import InputError from '@/Components/InputError.vue'; import { Link, useForm } from '@inertiajs/vue3'; const props=defineProps({product:{type:Object,required:true},plan:{type:Object,default:null}}); const form=useForm({name:props.plan?.name||'',slug:props.plan?.slug||'',description:props.plan?.description||'',billing_cycle:props.plan?.billing_cycle||'monthly',price:props.plan?.price??'',currency:props.plan?.currency||'NGN',setup_fee:props.plan?.setup_fee||0,trial_days:props.plan?.trial_days||0,grace_period_days:props.plan?.grace_period_days||0,is_active:props.plan?.is_active??true,is_public:props.plan?.is_public??true,sort_order:props.plan?.sort_order||0,metadata:props.plan?.metadata||{},features:(props.plan?.features||[]).map(({feature_key,feature_name,description,enabled,limit_value})=>({feature_key,feature_name,description,enabled,limit_value:limit_value||''})),limits:(props.plan?.limits||[]).map(({limit_key,limit_name,limit_value,metadata})=>({limit_key,limit_name,limit_value:limit_value||'',metadata:metadata||{}}))}); const submit=()=>props.plan?form.put(route('admin.plans.update',props.plan.id)):form.post(route('admin.products.plans.store',props.product.slug));
</script>
<template><form class="form-card" @submit.prevent="submit"><div class="form-grid"><label>Name<input v-model="form.name" required/><InputError :message="form.errors.name"/></label><label>Slug<input v-model="form.slug" required/><InputError :message="form.errors.slug"/></label><label>Billing cycle<select v-model="form.billing_cycle"><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="semiannual">Semiannual</option><option value="annual">Annual</option><option value="one_time">One time</option><option value="custom">Custom</option></select><InputError :message="form.errors.billing_cycle"/></label><label>Currency<input v-model="form.currency" maxlength="3" required class="uppercase"/><InputError :message="form.errors.currency"/></label><label>Price per billing period<input v-model="form.price" type="number" min="0" step="0.01" :required="form.billing_cycle!=='custom'"/><InputError :message="form.errors.price"/></label><label>Setup fee<input v-model="form.setup_fee" type="number" min="0" step="0.01" required/><InputError :message="form.errors.setup_fee"/></label><label>Trial days<input v-model="form.trial_days" type="number" min="0" required/><InputError :message="form.errors.trial_days"/></label><label>Grace-period days<input v-model="form.grace_period_days" type="number" min="0" required/><InputError :message="form.errors.grace_period_days"/></label><label>Sort order<input v-model="form.sort_order" type="number" min="0" required/><InputError :message="form.errors.sort_order"/></label></div><label>Description<textarea v-model="form.description" rows="4"/><InputError :message="form.errors.description"/></label><div class="flex flex-wrap gap-6"><label class="flex items-center gap-2"><input v-model="form.is_active" type="checkbox" class="!mt-0"/>Active</label><label class="flex items-center gap-2"><input v-model="form.is_public" type="checkbox" class="!mt-0"/>Visible publicly</label></div>
<InputError :message="form.errors.features"/><section class="space-y-4 border-t border-slate-200 pt-6"><div class="flex justify-between"><div><h2 class="text-xl font-bold">Features</h2><p class="text-sm text-slate-500">Saved features appear on pricing and checkout pages. Purchased features are preserved for existing subscriptions.</p></div><button type="button" class="form-secondary-button" @click="form.features.push({feature_key:'',feature_name:'',description:'',enabled:true,limit_value:''})">Add feature</button></div><div v-for="(feature,index) in form.features" :key="index" class="rounded-xl border border-slate-200 p-4"><div class="form-grid"><label>Feature key<input v-model="feature.feature_key" required placeholder="max_users"/></label><label>Display name<input v-model="feature.feature_name" required/></label><label>Description<textarea v-model="feature.description" rows="2"/></label><label>Limit value<input v-model="feature.limit_value" placeholder="Unlimited or 25"/></label></div><div class="flex justify-between"><label class="flex items-center gap-2"><input v-model="feature.enabled" type="checkbox" class="!mt-0"/>Enabled</label><button type="button" class="text-sm font-bold text-red-600" @click="form.features.splice(index,1)">Remove</button></div><InputError :message="form.errors[`features.${index}.feature_key`]"/></div></section>
<section class="space-y-4 border-t border-slate-200 pt-6"><div class="flex justify-between"><div><h2 class="text-xl font-bold">Limits</h2><p class="text-sm text-slate-500">Dedicated usage and capacity limits.</p></div><button type="button" class="form-secondary-button" @click="form.limits.push({limit_key:'',limit_name:'',limit_value:'',metadata:{}})">Add limit</button></div><div v-for="(limit,index) in form.limits" :key="index" class="rounded-xl border border-slate-200 p-4"><div class="form-grid"><label>Limit key<input v-model="limit.limit_key" required placeholder="max_branches"/></label><label>Display name<input v-model="limit.limit_name" required/></label><label>Value<input v-model="limit.limit_value"/></label></div><div class="text-right"><button type="button" class="text-sm font-bold text-red-600" @click="form.limits.splice(index,1)">Remove</button></div><InputError :message="form.errors[`limits.${index}.limit_key`]"/></div></section>
<div class="flex gap-3"><button class="form-button" :disabled="form.processing">{{ plan?'Save plan':'Create plan' }}</button><Link :href="route('admin.products.plans.index',product.slug)" class="rounded-xl border border-slate-300 px-6 py-3.5 font-bold">Cancel</Link></div></form></template>
